/// <summary>
/// Event button to click
/// </summary>
/// <param name="sender">
/// Controlbutton
/// </param>
/// <param name="e">
/// FormControlEventArgs
/// </param>
[FormControlEventHandler(formControlStr(WHSPackingWorkLocationSetup, AVAPrinterSetupButton), FormControlEventType::Clicked)]
public static void AVAPrinterSetupButton_OnClicked(FormControl sender, FormControlEventArgs e)
{
    WHSPackingWorkLocationSetup whsPackingWorkLocationSetup;
    FormRun                     element =  sender.formRun();
    FormDataSource              whsPackingWorkLocationSetup_ds  = element.dataSource();

    whsPackingWorkLocationSetup= whsPackingWorkLocationSetup_ds.cursor();

    whsPackingWorkLocationSetup.avaSetupPrinter();

    sender.hasChanged(true);
}
